preConditionHook:
// EEC E39 "Second Verse, (Almost) Same As The First" -- the book's
// composite, deliberately NOT split: Jan..lastLongMonth long-only /
// the rest short-only, a highest/lowest close, and the close's position
// in the bar's range.
// DELIBERATE DIVERGENCE FROM THE BOOK (Brian's call, 2026-08-31): the
// book writes (c-l)/(h-l) with NO epsilon, and EL raises a runtime
// divide-by-zero on a zero-range bar (the zero-denominator register
// row, measured). Both twins therefore carry E38's +.000001 epsilon --
// they stay identical to each other and diverge from the book only on
// bars where the book's own code would halt TradeStation.
svMonth = (int)civil_from_days(day_of(ctx.Time(0))).month;
svHighestC = close[0];
svLowestC = close[0];
for (int i = 1; i < (int)xbar; ++i) {
    if (el_gt(close[i], svHighestC)) { svHighestC = close[i]; }
    if (el_lt(close[i], svLowestC)) { svLowestC = close[i]; }
}
svRangePos = (close[0] - low[0]) / (high[0] - low[0] + 0.000001);
// `close = highest(...)` is the `=` trap: el_ge/el_le (Breakout).
